-- Baza demonstracyjna sklepu ogrodowego (dane w 100% syntetyczne)
-- Część 1: tabele TRANSAKCYJNE (tak, jak trzyma je system sklepu)
-- Część 2: widoki ANALITYCZNE v_* (model gwiazdy do Power BI)
-- Import: mysql -u root -p < ogrod_sklep.sql

SET NAMES utf8mb4;
DROP DATABASE IF EXISTS ogrod_sklep;
CREATE DATABASE ogrod_sklep CHARACTER SET utf8mb4 COLLATE utf8mb4_polish_ci;
USE ogrod_sklep;

-- ===================== CZĘŚĆ 1: TABELE TRANSAKCYJNE =====================

CREATE TABLE categories (
  category_id INT PRIMARY KEY,
  name VARCHAR(50) NOT NULL
);

CREATE TABLE products (
  product_id INT PRIMARY KEY,
  sku VARCHAR(10) NOT NULL UNIQUE,
  name VARCHAR(80) NOT NULL,
  category_id INT NOT NULL,
  vat_rate TINYINT NOT NULL,
  is_active TINYINT NOT NULL DEFAULT 1,
  created_at DATETIME NOT NULL,
  FOREIGN KEY (category_id) REFERENCES categories (category_id)
);

CREATE TABLE customers (
  customer_id INT PRIMARY KEY,
  customer_type ENUM('osoba', 'firma') NOT NULL,
  city VARCHAR(40) NOT NULL,
  voivodeship VARCHAR(30) NOT NULL,
  created_at DATETIME NOT NULL
);

CREATE TABLE orders (
  order_id INT PRIMARY KEY,
  order_number VARCHAR(20) NOT NULL UNIQUE,
  customer_id INT NOT NULL,
  channel ENUM('sklep', 'marketplace') NOT NULL,
  status ENUM('w_realizacji', 'zrealizowane', 'anulowane') NOT NULL,
  payment_method VARCHAR(30) NOT NULL,
  subtotal_gross DECIMAL(10,2) NOT NULL COMMENT 'brutto przed rabatem',
  discount_gross DECIMAL(10,2) NOT NULL,
  total_gross DECIMAL(10,2) NOT NULL COMMENT 'brutto po rabacie',
  total_net DECIMAL(10,2) NOT NULL COMMENT 'netto po rabacie',
  created_at DATETIME NOT NULL,
  updated_at DATETIME NOT NULL,
  KEY ix_orders_created (created_at),
  FOREIGN KEY (customer_id) REFERENCES customers (customer_id)
);

CREATE TABLE order_items (
  order_item_id INT PRIMARY KEY,
  order_id INT NOT NULL,
  product_id INT NOT NULL,
  quantity INT NOT NULL,
  unit_price_gross DECIMAL(10,2) NOT NULL COMMENT 'cena jednostkowa brutto w chwili zakupu',
  discount_gross DECIMAL(10,2) NOT NULL,
  row_total_gross DECIMAL(10,2) NOT NULL COMMENT 'wartość pozycji brutto po rabacie',
  row_total_net DECIMAL(10,2) NOT NULL COMMENT 'wartość pozycji netto po rabacie',
  unit_cost_net DECIMAL(10,2) NOT NULL COMMENT 'cena zakupu netto w chwili sprzedaży',
  FOREIGN KEY (order_id) REFERENCES orders (order_id),
  FOREIGN KEY (product_id) REFERENCES products (product_id)
);

CREATE TABLE returns (
  return_id INT PRIMARY KEY,
  return_number VARCHAR(20) NOT NULL UNIQUE,
  order_id INT NOT NULL,
  reason VARCHAR(40) NOT NULL,
  status ENUM('przyjęty', 'rozliczony') NOT NULL,
  created_at DATETIME NOT NULL,
  FOREIGN KEY (order_id) REFERENCES orders (order_id)
);

CREATE TABLE return_items (
  return_item_id INT PRIMARY KEY,
  return_id INT NOT NULL,
  order_item_id INT NOT NULL,
  quantity INT NOT NULL COMMENT '0 = reklamacja bez zwrotu towaru',
  refund_gross DECIMAL(10,2) NOT NULL,
  refund_net DECIMAL(10,2) NOT NULL,
  FOREIGN KEY (return_id) REFERENCES returns (return_id),
  FOREIGN KEY (order_item_id) REFERENCES order_items (order_item_id)
);

CREATE TABLE shipments (
  shipment_id INT PRIMARY KEY,
  order_id INT NOT NULL,
  carrier VARCHAR(30) NOT NULL,
  tracking_number VARCHAR(20) NOT NULL,
  shipped_at DATETIME NOT NULL,
  shipping_cost_net DECIMAL(10,2) NOT NULL,
  FOREIGN KEY (order_id) REFERENCES orders (order_id)
);


-- ===================== CZĘŚĆ 2: WIDOKI ANALITYCZNE =====================

-- Fakt: jeden wiersz = jedna pozycja zamówienia (bez anulowanych)
-- sales_net / cost_net / margin_net: tylko zamówienia zrealizowane, po odjęciu zwrotów;
-- zwroty przypisane do DATY ZAMÓWIENIA; koszt zwrotu proporcjonalny do zwróconej kwoty.
CREATE VIEW v_sales AS
SELECT oi.order_item_id, oi.order_id, DATE(o.created_at) AS order_date, o.customer_id, oi.product_id, oi.quantity,
  CAST(CASE WHEN o.status = 'zrealizowane' THEN oi.row_total_net - COALESCE(r.refund_net, 0) ELSE 0 END AS DECIMAL(12,2)) AS sales_net,
  CAST(CASE WHEN o.status = 'zrealizowane' THEN oi.unit_cost_net * oi.quantity * (1 - COALESCE(r.refund_net, 0) / oi.row_total_net) ELSE 0 END AS DECIMAL(12,2)) AS cost_net,
  CAST(CASE WHEN o.status = 'zrealizowane' THEN (oi.row_total_net - COALESCE(r.refund_net, 0)) - oi.unit_cost_net * oi.quantity * (1 - COALESCE(r.refund_net, 0) / oi.row_total_net) ELSE 0 END AS DECIMAL(12,2)) AS margin_net,
  CAST(CASE WHEN o.status = 'zrealizowane' THEN COALESCE(r.refund_net, 0) ELSE 0 END AS DECIMAL(12,2)) AS returns_net
FROM order_items oi
JOIN orders o ON o.order_id = oi.order_id
LEFT JOIN (
  SELECT order_item_id, SUM(refund_net) AS refund_net
  FROM return_items
  GROUP BY order_item_id
) r ON r.order_item_id = oi.order_item_id
WHERE o.status <> 'anulowane';

-- Wymiar: produkt z kategorią
CREATE VIEW v_products AS
SELECT p.product_id, p.sku, p.name AS product_name, c.name AS category_name
FROM products p
JOIN categories c ON c.category_id = p.category_id;

-- Wymiar: klient
CREATE VIEW v_customers AS
SELECT customer_id, customer_type, city, voivodeship
FROM customers;
